import {evaluate,professions,entryTypes,sources,sourceOf,extraFields,quickFilters,analytics,foundDate} from './strategy.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const list=a=>a.length?a.join(', '):'Не выявлено / недостаточно данных';
export function strategyBadges(j,profile){const s=evaluate(j,profile);return `<div class="strategy-badges"><span class="badge ${s.intern?'blue':''}">${esc(s.type)}</span><span class="badge">${s.professionPriority}. ${esc(s.profession)}</span><span class="badge">${s.format}</span><span class="badge ${s.language.fit==='Risk'?'risk':''}">Language: ${esc(s.language.fit)}</span><span class="badge ${s.score>=80?'good':s.score<40?'risk':''}">${esc(s.category)} · ${s.score}/100</span>${s.russiaEmploymentRisk?`<span class="badge risk">Russia employment risk · ${s.russiaRemoteConfirmed?'remote Georgia подтверждён':'уточнить'}</span>`:''}</div>`}
export function mountStrategy({getState,getToday,getTodayIds,getQuick,toggleQuick,showToday}){
 const $=s=>document.querySelector(s);
 const quick=document.createElement('div');quick.id='quick-filters';quick.className='quick-filters';quick.setAttribute('aria-label','Быстрые фильтры');quick.innerHTML=Object.entries(quickFilters).map(([k,v])=>`<button type="button" class="small-button" data-quick="${k}" aria-pressed="false">${v}</button>`).join('');$('.filters').before(quick);quick.onclick=e=>{const b=e.target.closest('[data-quick]');if(b)toggleQuick(b.dataset.quick)};
 $('#sort').insertAdjacentHTML('afterbegin','<option value="strategy">По стратегии: Internship → профессия → Remote → язык → стек → опыт</option>');$('#sort').value='strategy';
 const professionSelect=document.createElement('select');professionSelect.id='filter-profession';professionSelect.setAttribute('aria-label','Профессия по стратегии');professionSelect.innerHTML='<option value="">Все профессии</option>'+professions.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');$('.filters').prepend(professionSelect);
 const dashboard=document.createElement('section');dashboard.id='strategy-dashboard';dashboard.setAttribute('aria-label','Сводка поиска');$('.stats').after(dashboard);
 const advanced=document.createElement('details');advanced.className='strategy-fields';advanced.open=true;
 const select=(name,label,items)=>`<label>${label}<select name="${name}"><option value="">Авто / не указано</option>${items.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select></label>`;
 advanced.innerHTML=`<summary>Требования, источник и контакт</summary><div class="form-grid">${select('positionCategory','Position category',professions)}${select('positionType','Уровень позиции',[...entryTypes,'Junior','Middle','Senior','Unknown'])}${select('availability','Актуальность',['open','closed','unverified','program'])}<label>City<input name="city" maxlength="200"></label>${select('source','Source',sources)}<label>Required experience<input name="requiredExperience" maxlength="300" placeholder="0–1 year / 2+ years / не указано"></label>${select('englishLevel','English level',['None','A1','A2','B1','B2','Intermediate','C1','C2','Unknown'])}${select('georgianRequirement','Georgian requirement',['None','Conversational','Technical advanced','C1','Unknown'])}${select('russianRequirement','Russian requirement',['None','Required','Preferred','Unknown'])}${select('remoteEligibility','Работа из Georgia',['allowed','unknown','blocked'])}<label>Страна компании<input name="companyCountry" maxlength="200" placeholder="Russia / Georgia / …"></label>${select('requiresRussiaPresence','Проживание / присутствие в РФ',['yes','no','unknown'])}<label class="wide">Подтверждение remote из Грузии<textarea name="remoteEvidence" maxlength="2000" rows="2" placeholder="Цитата или ссылка: постоянная работа из Georgia разрешена"></textarea></label><label class="wide">Russia employment risk<textarea name="russiaEmploymentRisk" maxlength="2000" rows="2" placeholder="Что уточнить у HR: оформление, выплаты, воинский учёт"></textarea></label><label>Publication date<input name="publicationDate" type="date"></label><label>Significant update<input name="lastSignificantChange" type="date"></label><label>Date found<input type="date" name="dateFound"></label><label class="wide">Required stack<textarea name="requiredStack" maxlength="2000" rows="2" placeholder="Только требования работодателя: Python, SQL…"></textarea></label><label class="wide">Recruiter / contact<input name="recruiter" maxlength="1000" placeholder="Имя, email или ссылка"></label><label>Follow-up date<input name="followUpDate" type="date"></label><label class="wide">Cover letter used<textarea name="coverLetter" rows="3" maxlength="8000" placeholder="Текст отправленного письма или ссылка на версию"></textarea></label><label class="wide">Проекты для отклика<textarea name="portfolioProjects" rows="2" maxlength="2000"></textarea></label></div><p class="field-help">allowed = подтверждено; unknown = уточнить; blocked = запрещено. Неизвестное требование не означает отсутствие требования.</p>`;
 $('#interview-section').before(advanced);
 const analysis=document.createElement('details');analysis.id='automatic-analysis';analysis.className='automatic-analysis';$('#source-context').after(analysis);
 const refresh=document.createElement('label');refresh.className='wide';refresh.innerHTML='Need to refresh — навыки для повторения<textarea name="refreshSkills" rows="2" maxlength="2000" placeholder="Python, SQL, Git, Linux"></textarea>';$('#profile-form .form-grid').append(refresh);
 $('#profile-form .form-grid').insertAdjacentHTML('beforeend','<p class="wide field-help">Текущая география поиска: Georgia, Armenia, Europe; international remote только при явном допуске из Georgia. Стажировки в приоритете. Сохранённые навыки и портфолио остаются личными.</p>');
 $('#profile-form .context-box').innerHTML='<strong>Internship → Data / Analytics / Analyst / ML / BI → Remote</strong>Сортировка: Internship → Trainee/Graduate/Entry Level → Junior; затем профессия, Remote/Hybrid/On-site, язык, стек и опыт. Data Engineering → Analytics Engineering → Data Analyst → ML → BI → Engineering with Data Focus. Офис/гибрид в РФ и remote только по России исключены; российский remote допускается при подтверждённой постоянной работе из Грузии. Рейтинг 0–100: стартовый уровень до 25, профессия 20, целевой стек 20, формат 10, география 10, языки 10, опыт 5. Это эвристика, не вероятность оффера. Стек обучения не считается подтверждённым опытом. B2 — рабочая цель. Неизвестные требования требуют проверки.';
 const backupButton=document.createElement('button');backupButton.type='button';backupButton.className='secondary';backupButton.textContent='Скачать снимок до обновления';backupButton.onclick=async()=>{try{const r=await fetch('/api/backup',{cache:'no-store'});if(!r.ok)throw Error();const data=await r.json();if(!data.state){backupButton.textContent='Снимок появится перед первым сохранением';return}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data.state,null,2)],{type:'application/json'}));a.download='first-offer-before-strategy.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch{backupButton.textContent='Не удалось получить снимок — повтори позже'}};$('#backup-dialog .backup-body').append(backupButton);
 const pretty=k=>({foundToday:'Найдено сегодня',internships:'Стажировки',data:'Data Engineering',remote:'Remote',strong:'Strong match',today:'Apply today',applications:'Отклики',responses:'Ответы',interviews:'Интервью',rejections:'Отказы',conversion:'Ответы / отклики'}[k]||k);
 function render(){const state=getState(),today=getToday(),ids=getTodayIds();const a=analytics(state.jobs,state.profile,today,ids);quick.querySelectorAll('[data-quick]').forEach(b=>b.setAttribute('aria-pressed',String(getQuick().has(b.dataset.quick))));const tops=(arr)=>arr.slice(0,5).map(([k,v])=>`<li>${esc(k)} <b>${v}</b></li>`).join('')||'<li>Пока нет данных</li>';
 dashboard.innerHTML=`<div class="strategy-heading"><strong>Internship first · Data Engineering · Georgia / Armenia / Europe</strong><button class="small-button" id="dashboard-today">Откликнуться сегодня · ${ids.size}</button></div><div class="metric-grid">${['foundToday','internships','data','remote','strong','today','responses','interviews','rejections','conversion'].map(k=>`<div><b>${a[k]}${k==='conversion'?'%':''}</b><span>${pretty(k)}</span></div>`).join('')}</div><details class="weekly-summary"><summary>Неделя: ${a.weekly.applications} откликов · ${a.weekly.responses} ответов · аналитика</summary><p class="field-help">Понедельник–сегодня, Тбилиси. Ответы включают отказы, но не просмотры и автописьма. Отношение ответов к откликам — за всё время. События без дат не включаются в неделю.</p><div class="metric-grid">${['applications','responses','rejections','interviews','strong','internships','remote'].map(k=>`<div><b>${a.weekly[k]}</b><span>${pretty(k)}</span></div>`).join('')}</div><p>Чаще не хватает за неделю: <b>${esc(a.weekly.missing)}</b>. Английский в новых объявлениях: <b>${esc(a.weekly.language)}</b>.</p><div class="analytics-columns"><div><h3>Источники вакансий</h3><ul>${tops(a.sources)}</ul></div><div><h3>Профессии</h3><ul>${tops(a.professions)}</ul></div><div><h3>Missing skills</h3><ul>${tops(a.missing)}</ul></div></div></details>${a.warning?'<div class="strategy-warning">20+ релевантных откликов старше 7 дней без перехода к общению. Проверь CV, LinkedIn, GitHub, выбор вакансий, ширину фильтров и technical fit. Это сигнал для проверки, не диагноз причины.</div>':''}`;
 $('#dashboard-today').onclick=showToday;
 }
 function fillJob(j={}){const form=$('#job-form');for(const f of extraFields){if(form.elements[f])form.elements[f].value=j[f]||''}form.elements.availability.value=j.availability||(!j.id?'open':'unverified');form.elements.dateFound.value=foundDate(j)||getToday();form.elements.source.value=j.source||sourceOf(j);if(!j.id){form.elements.cvVersion.value=getState().profile.cvVersion||'';form.elements.cvUrl.value=getState().profile.cvUrl||''}renderAnalysis(j)}
 function renderAnalysis(j){const form=$('#job-form');const draft={...j,...Object.fromEntries(new FormData(form))};const s=evaluate(draft,getState().profile);analysis.innerHTML=`<summary>Автоматический разбор · ${s.category} · ${s.score}/100</summary>${strategyBadges(draft,getState().profile)}<dl><dt>Already know / Matching stack</dt><dd>${esc(list(s.matching))}</dd><dt>Need to refresh</dt><dd>${esc(list(s.needRefresh))}</dd><dt>Need to learn / Missing skills</dt><dd>${esc(list(s.missing))}</dd><dt>Language risk</dt><dd>${esc(s.language.risk)}</dd><dt>Russia employment risk / remote-from-Georgia</dt><dd>${esc(s.russiaEmploymentRisk||'Не выявлен по заполненным полям')} · ${esc(s.geo)}</dd><dt>Why apply</dt><dd>${esc(s.why)}</dd><dt>Приоритеты</dt><dd>Internship: ${s.internshipPriority} · Remote: ${s.remotePriority} · Data Engineering: ${s.dataEngineeringPriority}</dd><dt>Оценка / Overall relevance</dt><dd>${s.score}/100 · уровень ${s.parts.level}, профессия ${s.parts.profession}, стек ${s.parts.stack}, формат ${s.parts.format}, география ${s.parts.geography}, языки ${s.parts.language}, опыт ${s.parts.experience}; штрафы за senior, 2+ лет, языки и географию.</dd></dl><p class="field-help">Разбор по указанным требованиям, не AI-проверка страницы. Добавь полный стек и опыт для точности. Неизвестные технологии вне словаря проверь вручную.</p>`}
 return{render,fillJob,renderAnalysis};
}
